const craft = `
allegory|noun|D|A narrative whose characters and events sustain a second level of meaning.|The island story operates as an [[allegory]] of political corruption.|political allegory; sustained allegory|An allegory develops a broader correspondence; one symbolic object is insufficient.
allusion|noun|D|An indirect reference to a recognisable text, event, person or cultural idea.|The forbidden fruit introduces a biblical [[allusion]] that complicates the apparent innocence of the garden.|literary allusion; historical allusion|Identify the reference and explain what it contributes to this context.
archetype|noun|A|A recurring model of character, situation or image across stories.|The wandering stranger draws on the [[archetype]] of the outsider who unsettles a community.|heroic archetype; archetypal journey|Explain the recurring pattern instead of assuming all similar characters are identical.
motif|noun|D|A recurring detail or pattern that contributes to a text's meaning.|The recurring locked door becomes a [[motif]] of restricted possibility.|recurring motif; visual motif|A motif must recur; a one-off detail may still be symbolic.
symbolism|noun|D|The use of concrete details to suggest meanings beyond their literal presence.|The broken watch introduces [[symbolism]] that connects damaged objects with lives interrupted by war.|visual symbolism; symbolic significance|Support symbolic interpretations with context and repetition where available.
metaphor|noun|F|A comparison that describes one thing in terms of another without literal equivalence.|The city's description as a hungry animal creates a [[metaphor]] for collective exploitation.|extended metaphor; spatial metaphor|Explain the specific shared quality rather than merely identifying the comparison.
simile|noun|F|An explicit comparison, often using like or as.|The comparison of the crowd to drifting smoke is a [[simile]] that stresses its instability.|striking simile; comparative simile|Not every use of like or as introduces a figurative comparison.
imagery|noun|D|Descriptive language that evokes sensory experience.|The sour smell and sticky heat create [[imagery]] that makes the room physically oppressive.|sensory imagery; tactile imagery|Imagery can evoke any sense, not only sight.
irony|noun|D|A meaningful discrepancy between appearance and reality, statement and meaning, or expectation and outcome.|The prison's name, Liberty House, establishes an [[irony]] that exposes official hypocrisy.|situational irony; verbal irony|Explain the discrepancy; an unfortunate coincidence is not automatically ironic.
juxtaposition|noun|D|The close placement of contrasting or revealing elements.|The [[juxtaposition]] of the banquet and famine exposes the ruling class's indifference.|visual juxtaposition; structural juxtaposition|Identify both elements and explain why placing them together matters.
foreshadowing|noun|D|An earlier detail that prepares readers for a later development.|The cracked beam provides [[foreshadowing]] of the house's eventual collapse.|subtle foreshadowing; ominous foreshadowing|Connect the earlier clue to a later event rather than predicting without evidence.
flashback|noun|F|A scene that interrupts the present narrative to depict an earlier event.|The childhood [[flashback]] reframes the mother's apparently unreasonable fear.|extended flashback; retrospective flashback|A brief mention of the past is not necessarily a fully represented flashback.
prolepsis|noun|A|A narrative movement forward to an event later than the current story time.|The glimpse of the ruined house is a [[prolepsis]] that unsettles the present celebration.|narrative prolepsis; anticipatory prolepsis|Unlike foreshadowing, prolepsis directly narrates or presents a future event.
chronology|noun|D|The arrangement of events according to when they occur.|The disrupted [[chronology]] makes the reader reconstruct the causes of the separation.|linear chronology; disrupted chronology|Distinguish the order of events from the order in which they are narrated.
temporality|noun|A|The way time is experienced, organised or represented.|The lingering description alters the scene's [[temporality]], stretching a moment of recognition.|narrative temporality; subjective temporality|Explain the particular treatment of time rather than using it as a decorative synonym.
anachronism|noun|A|An element placed in a period to which it does not historically belong.|The modern alarm clock is a deliberate [[anachronism]] within the medieval court.|deliberate anachronism; historical anachronism|Check the historical mismatch and consider whether it is purposeful.
retrospection|noun|A|Looking back on past events from a later position.|The narrator's [[retrospection]] introduces regret unavailable to her younger self.|narrative retrospection; reflective retrospection|Distinguish later reflection from simply narrating events in the past tense.
ellipsis|noun|A|The omission of material, words or a span of story time.|The ten-year [[ellipsis]] leaves the reader to infer how the friendship deteriorated.|narrative ellipsis; grammatical ellipsis|Specify whether the omission concerns wording, punctuation or story time.
exposition|noun|D|Information that establishes the situation, background or relationships of a story.|The opening [[exposition]] presents the inheritance as both opportunity and burden.|opening exposition; economical exposition|Exposition provides context; it is not necessarily the entire introduction.
complication|noun|D|A development that introduces or intensifies a narrative problem.|The missing will creates a [[complication]] that turns grief into rivalry.|narrative complication; escalating complication|Identify how the event changes the existing conflict.
climax|noun|F|The point at which a narrative's central conflict reaches greatest intensity or a decisive turn.|The public confession forms the [[climax]] of the struggle between loyalty and truth.|dramatic climax; narrative climax|The climax is not automatically the final scene.
anticlimax|noun|D|A reduction of intensity where a significant resolution was expected.|The dispute ends over a misplaced receipt, producing an [[anticlimax]] that punctures heroic pretensions.|comic anticlimax; deliberate anticlimax|Explain the expectation and the deflating outcome.
denouement|noun|A|The stage after a climax in which consequences and remaining narrative threads unfold.|The quiet [[denouement]] reveals that victory has not repaired the family.|extended denouement; unresolved denouement|A denouement follows the central turning point and need not solve every problem.
resolution|noun|D|The settling or concluding treatment of a narrative's central conflict.|The tentative [[resolution]] restores contact without erasing the siblings' distrust.|partial resolution; narrative resolution|An ending may deliberately withhold full resolution.
coda|noun|A|A brief concluding section that adds perspective after the main ending.|The final letter acts as a [[coda]], questioning the reconciliation just achieved.|reflective coda; narrative coda|A coda is an additional concluding movement, not any final sentence.
epilogue|noun|D|A separate concluding section describing events after the main narrative.|The [[epilogue]] reveals how the next generation inherits the unresolved conflict.|retrospective epilogue; closing epilogue|Distinguish a formally separate epilogue from an ordinary final chapter.
prologue|noun|D|An introductory section that precedes the main narrative.|The anonymous warning in the [[prologue]] casts suspicion over the apparent idyll.|dramatic prologue; introductory prologue|Explain how the preliminary section frames later interpretation.
framing|noun|D|The contextual or structural arrangement that shapes how material is understood.|The courtroom [[framing]] makes every memory appear as contested evidence.|narrative framing; visual framing|Clarify whether the frame is structural, interpretive or visual.
circularity|noun|A|A structure that returns to its beginning or repeats its central pattern.|The return to the empty station creates a [[circularity]] that questions the journey's progress.|structural circularity; narrative circularity|A repeated detail suggests circularity only when it meaningfully connects ending and beginning.
linearity|noun|A|An arrangement that proceeds in a continuous sequential order.|The story's apparent [[linearity]] is interrupted by memories that resist orderly explanation.|narrative linearity; chronological linearity|Linear sequence does not necessarily produce a simple meaning.
episodic|adjective|D|Organised into relatively distinct incidents or sections.|The [[episodic]] structure presents migration as a succession of uncertain beginnings.|episodic structure; episodic narrative|Explain the relation between episodes rather than assuming they are disconnected.
cyclical|adjective|D|Following a recurring pattern that returns to an earlier stage.|The [[cyclical]] pattern of accusation and apology suggests that nothing fundamental changes.|cyclical structure; cyclical violence|Cyclical repetition involves a returning pattern, not any repeated word.
montage|noun|A|A sequence of selected images or scenes assembled to create a condensed meaning.|The [[montage]] of factory clocks compresses years of repetitive labour.|visual montage; cinematic montage|Discuss how the assembled pieces work together, not merely the presence of cuts.
vignette|noun|A|A brief, focused scene that captures a revealing moment or impression.|The market [[vignette]] reveals everyday cooperation absent from the official account.|domestic vignette; brief vignette|A vignette usually offers a concentrated impression rather than a full plot.
tableau|noun|A|A striking scene arranged like a still picture.|The family frozen around the untouched meal forms a [[tableau]] of emotional paralysis.|dramatic tableau; symbolic tableau|The term emphasises a composed, relatively static visual arrangement.
perspective|noun|D|The position or outlook through which events are perceived or interpreted.|The child's [[perspective]] makes the adults' euphemisms appear both strange and evasive.|limited perspective; shifting perspective|Name whose outlook shapes the representation.
focalisation|noun|A|The filtering of narrative information through a particular perceiving consciousness.|The narrow [[focalisation]] restricts readers to what the frightened daughter notices.|internal focalisation; shifting focalisation|Who perceives may differ from who narrates.
narration|noun|D|The act and manner of telling a story.|The restrained [[narration]] allows disturbing events to emerge without overt judgement.|first-person narration; retrospective narration|Describe the telling voice separately from the author's personal beliefs.
omniscience|noun|A|A narrator's apparent access to knowledge beyond any single character.|The narrator's [[omniscience]] reveals the private fears on both sides of the argument.|narrative omniscience; apparent omniscience|Omniscience is broader than access to one character's thoughts.
unreliability|noun|D|A narrator's limited trustworthiness as a source of facts or interpretation.|The contradicted dates establish the narrator's [[unreliability]] before his confession.|narrative unreliability; interpretive unreliability|Identify evidence of distortion rather than assuming first-person narrators are unreliable.
subjectivity|noun|D|The influence of personal experience, perception or feeling on an account.|The selective memories foreground the [[subjectivity]] of the family history.|individual subjectivity; subjective perception|Subjectivity does not necessarily make every factual claim false.
objectivity|noun|D|An attempt to describe or judge without personal bias.|The clinical style creates an appearance of [[objectivity]] that the selective details undermine.|apparent objectivity; claim to objectivity|An impersonal style can still express values or omissions.
interiority|noun|A|A character's inward thoughts, emotions and private mental experience.|The journal grants access to an [[interiority]] concealed by her obedient public role.|psychological interiority; female interiority|Interiority concerns inner experience, not merely an indoor setting.
introspection|noun|D|The examination of one's own thoughts, feelings or motives.|His late [[introspection]] exposes the selfishness he once called duty.|painful introspection; sustained introspection|Self-examination may be incomplete or self-serving rather than automatically insightful.
soliloquy|noun|A|A dramatic speech in which a character voices private thoughts, conventionally unheard by others.|The [[soliloquy]] exposes doubts the commander conceals from his soldiers.|dramatic soliloquy; revealing soliloquy|A soliloquy reveals private thought; a monologue can address other characters.
monologue|noun|D|An extended speech delivered by one speaker.|Her uninterrupted [[monologue]] briefly overturns the household's usual distribution of power.|dramatic monologue; extended monologue|Identify the audience and situation rather than assuming the speaker is alone.
dialogue|noun|F|An exchange of speech between characters or voices.|The interrupted [[dialogue]] shows how authority controls whose story can be heard.|fragmented dialogue; tense dialogue|Discuss turn-taking, interruptions or diction instead of only stating that characters speak.
aside|noun|D|A brief dramatic remark conventionally heard by the audience but not other characters.|His reassuring promise is undercut by an [[aside]] revealing contempt.|dramatic aside; conspiratorial aside|Distinguish the theatrical convention from an ordinary private conversation.
subtext|noun|D|An implied meaning beneath what is explicitly said or shown.|The polite discussion of weather carries a [[subtext]] of accusation.|emotional subtext; political subtext|Ground inferred meaning in wording, context or performance details.
intertextuality|noun|A|The ways a text gains meaning through relationships with other texts.|The rewritten fairy tale foregrounds [[intertextuality]] by challenging the familiar rescue ending.|literary intertextuality; intertextual relationship|Explain the specific textual relationship and its effect.
metafiction|noun|A|Fiction that draws attention to its own construction or status as fiction.|The narrator's argument with the author turns the novel into [[metafiction]].|self-conscious metafiction; metafictional device|A fictional narrator alone does not make a work metafictional.
self-reflexivity|noun|A|A work's attention to its own methods, form or conditions of creation.|The visible camera introduces [[self-reflexivity]] by exposing the act of filming.|formal self-reflexivity; self-reflexive narration|Identify the work's reflection on its own representation.
bildungsroman|noun|A|A novel centred on a protagonist's formative development towards adulthood.|The unfinished apprenticeship revises the [[bildungsroman]] by withholding a stable adult identity.|traditional bildungsroman; female bildungsroman|Not every story featuring a young character traces formative development.
tragedy|noun|D|A dramatic or narrative form centred on grave suffering and often irreversible downfall.|The preventable exile gives the [[tragedy]] its force by preserving the possibility of another outcome.|domestic tragedy; classical tragedy|Distinguish the literary form from the everyday label for any sad event.
comedy|noun|D|A literary or dramatic form that uses humour and often social disruption or reconciliation.|The mistaken identities allow the [[comedy]] to challenge rigid assumptions about status.|social comedy; romantic comedy|Comedy can critique serious issues and need not be merely light entertainment.
tragicomedy|noun|A|A work combining tragic and comic elements without fully resolving their tension.|The absurd funeral arrangements make the play a [[tragicomedy]] of grief and social performance.|modern tragicomedy; tragicomic effect|Explain how suffering and humour interact rather than simply listing both.
satire|noun|D|The use of ridicule, irony or exaggeration to expose faults or abuses.|The minister's endless medals make the scene a [[satire]] of empty public honour.|political satire; social satire|Identify the target and criticism; humour alone is not satire.
elegy|noun|A|A poem or reflective work expressing mourning, often for a death or lost world.|The closing reflection becomes an [[elegy]] for the neighbourhood erased by redevelopment.|pastoral elegy; elegy for a lost world|An elegy mourns loss; it is not any melancholy description.
pastoral|adjective|A|Representing rural life through an idealised or reflective literary tradition.|The opening's [[pastoral]] imagery is unsettled by the labour hidden beyond the meadow.|pastoral imagery; pastoral ideal|Pastoral is a literary treatment of rural life, not simply a country setting.
gothic|adjective|A|Using unsettling spaces, fear, secrecy or haunting to explore psychological and social anxieties.|The locked corridor gives the domestic setting a [[gothic]] menace.|gothic atmosphere; gothic convention|Connect conventions to the anxieties they express rather than listing dark objects.
dystopia|noun|D|An imagined society marked by oppressive, harmful or deeply undesirable conditions.|The compulsory happiness tests expose a [[dystopia]] concealed beneath cheerful slogans.|technological dystopia; dystopian society|A difficult setting is not necessarily a systematic imagined social order.
utopia|noun|D|An imagined society presented as ideally organised or free from major social problems.|The island's apparent [[utopia]] depends on labour its visitors are forbidden to see.|apparent utopia; utopian ideal|Utopian appearances may be questioned rather than endorsed by the text.
realism|noun|D|A mode that represents recognisable life through plausible detail and social circumstance.|The unpaid bills anchor the story's [[realism]] in everyday economic pressure.|social realism; realist detail|Realism is a representational approach, not proof that events actually happened.
naturalism|noun|A|A literary mode stressing the influence of environment, heredity and material conditions on behaviour.|The protagonist's constrained choices reflect a [[naturalism]] that questions unrestricted free will.|literary naturalism; naturalistic determinism|Naturalism is not simply vivid description of nature.
modernism|noun|A|A movement associated with experimentation in form and challenges to inherited certainties.|The fractured chronology and interior voice locate the novel within [[modernism]].|literary modernism; modernist experimentation|Modernism names a movement, not everything recently written.
postmodernism|noun|A|An approach associated with self-conscious form, unstable meaning and challenges to universal accounts.|The contradictory endings reflect [[postmodernism]] in their challenge to a single authoritative account.|literary postmodernism; postmodern uncertainty|Support the label with specific formal features and relevant context.
romanticism|noun|A|A movement valuing imagination, emotion and individual experience, often in relation to nature.|The solitary encounter with the mountains recalls the priorities of [[romanticism]].|literary romanticism; romantic imagination|Romanticism as a movement is not synonymous with a love story.
verisimilitude|noun|A|The appearance of truth or convincing lifelikeness in a representation.|The precise bus routes give the invented city [[verisimilitude]].|social verisimilitude; create verisimilitude|A convincing appearance does not establish factual truth.
ambiguity|noun|D|The presence of more than one plausible meaning or interpretation.|The unfinished promise preserves [[ambiguity]] about whether she intends to return.|moral ambiguity; deliberate ambiguity|Explain the competing interpretations rather than equating ambiguity with confusion.
polysemy|noun|A|The capacity of a word or sign to carry several related meanings.|The [[polysemy]] of home connects physical shelter with emotional acceptance.|lexical polysemy; polysemous imagery|Identify distinct related meanings activated by the context.
indeterminacy|noun|A|The inability to settle a meaning or outcome conclusively from the available evidence.|The missing final page makes [[indeterminacy]] central to the reader's experience.|narrative indeterminacy; interpretive indeterminacy|Indeterminacy is sustained openness, not simply poor comprehension.
characterisation|noun|D|The methods through which a text constructs a character's qualities and complexity.|Indirect [[characterisation]] emerges through the gifts she keeps but refuses to acknowledge.|indirect characterisation; nuanced characterisation|Discuss a method such as action, dialogue or perspective rather than only listing traits.
protagonist|noun|F|The central character whose experiences organise much of a narrative.|The [[protagonist]] remains morally compromised even as the narrative invites sympathy.|central protagonist; flawed protagonist|The protagonist is not necessarily admirable or heroic.
antagonist|noun|D|A character or force that opposes the protagonist's aims.|The institution functions as an [[antagonist]] even when no individual official appears wholly cruel.|institutional antagonist; principal antagonist|An antagonist need not be a villain or even a single person.
foil|noun|A|A character whose differences bring another character's qualities into clearer focus.|The cautious sister acts as a [[foil]] to her brother's reckless ambition.|character foil; dramatic foil|Explain the revealing contrast; a foil is not simply an enemy.
antihero|noun|D|A central character lacking qualities conventionally associated with heroic conduct.|The evasive narrator becomes an [[antihero]] whose survival depends on compromise.|flawed antihero; reluctant antihero|An antihero occupies a central role; the term is not another word for villain.
ensemble|noun|D|A group of characters or performers whose combined roles carry a work.|The [[ensemble]] distributes the community's story across competing experiences.|ensemble cast; ensemble narrative|An ensemble implies meaningful shared prominence, not merely many minor characters.
caricature|noun|D|An exaggerated representation that reduces a person to conspicuous traits.|The pompous official begins as a [[caricature]] before private grief complicates him.|comic caricature; political caricature|Caricature simplifies and exaggerates; detailed characterisation may later resist it.
personification|noun|D|Giving human qualities or actions to non-human things or abstract ideas.|The city's refusal to sleep creates a [[personification]] of relentless collective activity.|urban personification; personification of fear|Identify the specifically human quality attributed to the non-human subject.
anthropomorphism|noun|A|Representing non-human beings as possessing sustained human characteristics or behaviour.|The animals' courtroom depends on [[anthropomorphism]] to expose human legal absurdity.|animal anthropomorphism; anthropomorphic character|Usually more sustained character-like humanisation than a passing personification.
zoomorphism|noun|A|Representing humans or other entities through animal qualities.|The crowd's snapping and snarling creates a [[zoomorphism]] that diminishes individual judgement.|animalistic zoomorphism; zoomorphic imagery|Explain how the animal comparison shapes judgement of its subject.
pathetic fallacy|phrase|A|The attribution of human emotion to nature or the environment.|The grieving sky uses [[pathetic fallacy]] to externalise the speaker's sorrow.|use of pathetic fallacy; emotional landscape|Weather that merely occurs alongside emotion is not automatically given human feeling.
setting|noun|F|The time, place and social environment in which events occur.|The coastal [[setting]] makes departure a constant possibility rather than a distant dream.|historical setting; claustrophobic setting|Analyse the setting's function instead of only naming its location.
atmosphere|noun|D|The prevailing emotional impression created by a scene's details.|The muffled footsteps create an [[atmosphere]] of anticipation and unease.|oppressive atmosphere; tense atmosphere|Distinguish the scene's atmosphere from a speaker's attitude or tone.
milieu|noun|A|The surrounding social and cultural environment.|The competitive academic [[milieu]] rewards performances of certainty over honest doubt.|social milieu; intellectual milieu|Milieu usually emphasises social surroundings rather than physical scenery alone.
topography|noun|A|The physical features and spatial arrangement of a place.|The city's divided [[topography]] turns social hierarchy into a map of hills and lowlands.|urban topography; symbolic topography|Connect spatial features to meaning without losing their literal geography.
threshold|noun|D|A boundary or point of transition between spaces or conditions.|Her pause at the doorway makes the [[threshold]] a site of contested belonging.|symbolic threshold; cross a threshold|Explain the two states or spaces linked by the boundary.
microcosm|noun|A|A small setting or group that reflects patterns in a larger world.|The divided household becomes a [[microcosm]] of the nation's class conflict.|social microcosm; domestic microcosm|Demonstrate the correspondence between the small unit and the larger system.
macrocosm|noun|A|A larger whole reflected or represented within a smaller unit.|The household's divisions echo the political [[macrocosm]] beyond its walls.|social macrocosm; relation to the macrocosm|Use in relation to a smaller representative unit rather than for anything merely large.
defamiliarisation|noun|A|Making familiar things seem strange so that readers perceive them afresh.|The child's literal description of money produces [[defamiliarisation]] of ordinary economic habits.|linguistic defamiliarisation; defamiliarising perspective|Explain what becomes unfamiliar and what fresh insight this permits.
synaesthesia|noun|A|A description that combines or crosses different sensory modes.|The phrase bitter music uses [[synaesthesia]] to give sound the quality of taste.|sensory synaesthesia; synaesthetic imagery|Identify the senses being crossed; multiple separate sensory details are not enough.
omission|noun|D|The deliberate or significant absence of information or material.|The mother's [[omission]] from the family photograph exposes a history the household suppresses.|significant omission; narrative omission|Do not assume intent without evidence; explain the effect of the absence.
pacing|noun|D|The rate at which a narrative presents events and information.|The slowed [[pacing]] forces attention onto the hesitation before her answer.|deliberate pacing; accelerated pacing|Link speed to devices such as description, scene length or withheld information.
cadence|noun|A|The characteristic flow or rise and fall of language, especially at phrase endings.|The repeated falling [[cadence]] gives the speech a weary finality.|measured cadence; elegiac cadence|Attend to audible phrasing rather than using cadence for general style.
rhythm|noun|D|A pattern of movement created by stresses, sounds or repeated units.|The abrupt [[rhythm]] of the short clauses conveys the runner's mounting panic.|syntactic rhythm; disrupted rhythm|Describe the pattern and its effect rather than assuming all rhythm is regular.
syntax|noun|D|The arrangement of words and clauses into sentences.|The suspended [[syntax]] delays the accusation until the final phrase.|fragmented syntax; complex syntax|Syntax concerns arrangement; diction concerns word choice.
diction|noun|D|The particular words and kinds of vocabulary chosen in a text.|The legalistic [[diction]] turns a family dispute into an impersonal contest of claims.|formal diction; evaluative diction|Quote or identify particular choices instead of treating diction as language in general.
register|noun|D|A style of language associated with a context, purpose or social relationship.|The shift to an intimate [[register]] briefly dismantles the distance between employer and worker.|formal register; conversational register|Register depends on context and purpose, not simply a word's difficulty.
vernacular|noun|A|The everyday language used by a particular community.|The local [[vernacular]] gives authority to experiences excluded from official accounts.|regional vernacular; everyday vernacular|Avoid treating vernacular speech as inherently incorrect or inferior.
idiolect|noun|A|The distinctive language habits of an individual speaker.|Her clipped questions and habitual qualifiers establish a recognisable [[idiolect]].|individual idiolect; distinctive idiolect|An idiolect belongs to an individual; a dialect belongs to a social or regional group.
`;

type Category = Word["category"];
function unpack(source: string, category: Category): Word[] {
  return source
    .trim()
    .split("\n")
    .filter(Boolean)
    .map((line) => {
      const [
        word,
        partOfSpeech,
        difficulty,
        definition,
        marked,
        combinations,
        caution,
      ] = line.split("|");
      const answer = marked.match(/\[\[(.+?)\]\]/)?.[1];
      if (!answer || !caution)
        throw new Error(`Malformed vocabulary entry: ${word}`);
      return {
        id: word.toLowerCase().replace(/[^a-z0-9]+/g, "-"),
        word,
        partOfSpeech: partOfSpeech as Word["partOfSpeech"],
        category,
        level: ({ F: "Foundation", D: "Developing", A: "Advanced" } as const)[
          difficulty as "F" | "D" | "A"
        ],
        definition,
        example: marked.replace(/\[\[(.+?)\]\]/, "$1"),
        collocations: combinations.split("; "),
        caution,
        gap: marked.replace(/\[\[(.+?)\]\]/, "___"),
        answer,
      };
    });
}

export const literaryWords: Word[] = [
  ...unpack(themes, "Themes & ideas"),
  ...unpack(character, "Character & society"),
  ...unpack(craft, "Literary craft"),
];
